const getOptions = (input, { copy, wrap }) => {
  const result = {}
  if (input && typeof input === 'object') {
    for (const prop of copy) {
      if (input[prop] !== undefined) {
        result[prop] = input[prop]
      }
    }
  } else {
    result[wrap] = input
  }
  return result
}
module.exports = getOptions
